cd /workspaces/semio && python3 << 'PYEOF'
import json

with open('semio/assets/semio/kit_metabolism.json') as f:
    kit = json.load(f)

# Helper: strip all array fields from a dict (Meta)
def to_meta(d):
    return {k: v for k, v in d.items() if not isinstance(v, list)}

# Helper: strip all array fields from sub-entity items but keep them as meta in parent (Shallow) 
def to_shallow_kit(kit_data):
    result = {}
    for k, v in kit_data.items():
        if isinstance(v, list):
            result[k] = [to_meta(item) if isinstance(item, dict) else item for item in v]
        else:
            result[k] = v
    return result

# Helper: strip the blob field from files in addition to meta
def to_meta_kit(kit_data):
    meta = to_meta(kit_data)
    return meta

# === KIT META ===
kit_meta = to_meta(kit)
with open('semio/assets/semio/metabolism.meta.kit.semio.json', 'w') as f:
    json.dump(kit_meta, f, indent=2)
print(f"metabolism.meta.kit.semio.json: {len(json.dumps(kit_meta))} bytes, keys: {list(kit_meta.keys())}")

# === KIT SHALLOW ===
kit_shallow = to_shallow_kit(kit)
with open('semio/assets/semio/metabolism.shallow.kit.semio.json', 'w') as f:
    json.dump(kit_shallow, f, indent=2)
print(f"metabolism.shallow.kit.semio.json: {len(json.dumps(kit_shallow))} bytes")

# === DESIGN META (Nakagin Capsule Tower) ===
for d in kit['designs']:
    if d.get('name') == 'Nakagin Capsule Tower':
        design_meta = to_meta(d)
        with open('semio/assets/semio/nakagin-capsule-tower.meta.design.semio.json', 'w') as f:
            json.dump(design_meta, f, indent=2)
        print(f"nakagin-capsule-tower.meta.design.semio.json: keys: {list(design_meta.keys())}")

        design_shallow = {}
        for k, v in d.items():
            if isinstance(v, list):
                design_shallow[k] = [to_meta(item) if isinstance(item, dict) else item for item in v]
            else:
                design_shallow[k] = v
        with open('semio/assets/semio/nakagin-capsule-tower.shallow.design.semio.json', 'w') as f:
            json.dump(design_shallow, f, indent=2)
        print(f"nakagin-capsule-tower.shallow.design.semio.json: {len(json.dumps(design_shallow))} bytes")
        break

# === TYPE META (Tambour) ===
for t in kit['types']:
    if t.get('name') == 'Tambour':
        type_meta = to_meta(t)
        with open('semio/assets/semio/tambour.meta.type.semio.json', 'w') as f:
            json.dump(type_meta, f, indent=2)
        print(f"tambour.meta.type.semio.json: keys: {list(type_meta.keys())}")

        type_shallow = {}
        for k, v in t.items():
            if isinstance(v, list):
                type_shallow[k] = [to_meta(item) if isinstance(item, dict) else item for item in v]
            else:
                type_shallow[k] = v
        with open('semio/assets/semio/tambour.shallow.type.semio.json', 'w') as f:
            json.dump(type_shallow, f, indent=2)
        print(f"tambour.shallow.type.semio.json: {len(json.dumps(type_shallow))} bytes")
        break

print("\nDone creating all 6 test asset files.")
